public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    boolean[] used = new boolean[nums.length];
    List<Integer> current = new ArrayList<>();
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    String first = strings.get(0);
    int maxLength = 0;

    for (int i = 0; i < first.length(); i++) {
        for (int j = i + 1; j <= first.length(); j++) {
            String substring = first.substring(i, j);
            String reversedSubstring = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String str : strings) {
                if (!str.contains(substring) && !str.contains(reversedSubstring)) {
                    allContain = false;
                    break;
                }
            }

            if (allContain) {
                maxLength = Math.max(maxLength, substring.length());
            }
        }
    }

    return maxLength;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                dfs(grid, visited, i, j);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col) {
    int[] rowDirections = {-1, -1, -1, 0, 1, 1, 1, 0};
    int[] colDirections = {-1, 0, 1, 1, 1, 0, -1, -1};

    visited[row][col] = true;

    for (int d = 0; d < 8; d++) {
        int newRow = row + rowDirections[d];
        int newCol = col + colDirections[d];

        if (isValid(grid, visited, newRow, newCol)) {
            dfs(grid, visited, newRow, newCol);
        }
    }
}

private static boolean isValid(char[][] grid, boolean[][] visited, int row, int col) {
    return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length && grid[row][col] == '@' && !visited[row][col];
}

public static int maxRegions(int N) {
