public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            if (path[0] == current[0] && path[1] == current[1]) {
                int newX = path[2];
                int newY = path[3];
                if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                    queue.offer(new int[]{newX, newY});
                    visited[newX][newY] = true;
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Words must not be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }

    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int commonLetters = 0;
    for (int i = 0; i < 26; i++) {
        commonLetters += Math.min(count1[i], count2[i]);
    }

    int totalLength = word1.length() + word2.length();

    int gcd = gcd(commonLetters, totalLength);

    int numerator = commonLetters / gcd;
    int denominator = totalLength / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + (denominator == 1 ? numerator : numerator + "/" + denominator);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String convertDatesToWeekdays(String date) {
    try {
        String[] dateParts = date.split(" ");
        if (dateParts.length != 3) {
            return "Invalid date format. Please use 'MM dd yyyy'.";
        }

        int month = Integer.parseInt(dateParts[0]);
        int day = Integer.parseInt(dateParts[1]);
        int year = Integer.parseInt(dateParts[2]);

        String[] months = {"January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"};
        String[] daysOfWeek = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

        if (month < 1 || month > 12 || day < 1 || day > 31) {
            return "Invalid date values.";
        }

        java.util.Calendar calendar = java.util.Calendar.getInstance();
        calendar.set(year, month - 1, day);
