}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainder
        remainderCount[remainder]++;
    }

    // Check if there is an even number of elements with remainder 0
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    return true;
}

int minTime(int n, int[][] edges, boolean[] hasApple) {
