    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }
    return dfs(0, -1, tree, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int totalTime = 0;
    for (int child : tree.get(node)) {
        if (child == parent) continue;
        int childTime = dfs(child, node, tree, hasApple);
        if (childTime > 0 || hasApple[child]) {
            totalTime += childTime + 2;
        }
    }
    return totalTime;
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    boolean forward = true;
    int remaining = s.length();

    while (remaining > 0) {
        if (forward) {
            for (int i = 0; i < 26; i++) {
                if (count[i] > 0) {
                    result.append((char) (i + 'a'));
                    count[i]--;
                    remaining--;
                }
            }
        } else {
            for (int i = 25; i >= 0; i--) {
                if (count[i] > 0) {
                    result.append((char) (i + 'a'));
                    count[i]--;
                    remaining--;
                }
            }
        }
        forward = !forward;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n / 2; i++) {
        for (int j = n - 1; j >= i; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j + 1][k + nums[j]] = true;
                    dp[i][j][k] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = i; j <= n; j++) {
            int k = sum * i / j;
            if (sum * i % j == 0 && dp[i][j][k]) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must have at least two elements.");
    }

    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[n - 1], dp[n - 2]);
}

public int uniqueMorseRepresentations(String[] words) {
    String[] morseCodes = {
