    Set<String> seen = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
        if (seen.size() == (1 << k)) {
            return true;
        }
    }

    return false;
}

