public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int sum = 0;
    int remaining = n;

    for (int i = 0; i < n; i++) {
        for (char c = 'a'; c <= 'z'; c++) {
            int value = c - 'a' + 1;
            if (sum + value + (remaining - 1) * 26 >= k) {
                result.append(c);
                sum += value;
                remaining--;
                break;
            }
        }
    }

    return result.toString();
}

