    StringBuilder result = new StringBuilder();
    int count = 0;

    while (n > 0) {
        if (count == 3) {
            result.append('.');
            count = 0;
        }
        result.append(n % 10);
        n /= 10;
        count++;
    }

    return result.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    boolean[] used = new boolean[A.length];
    int[] count = new int[1];
    backtrack(A, used, new int[A.length], count, 0);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int[] current, int[] count, int pos) {
    if (pos == A.length) {
        count[0]++;
        return;
    }
    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            if (pos == 0 || isPerfectSquare(current[pos - 1] + A[i])) {
                used[i] = true;
                current[pos] = A[i];
                backtrack(A, used, current, count, pos + 1);
                used[i] = false;
            }
            while (i + 1 < A.length && A[i] == A[i + 1]) {
                i++;
            }
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];
    int maxArea = 0;

    // Fill left array with the index of the nearest smaller element to the left of each element
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    // Fill right array with the index of the nearest smaller element to the right of each element
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    // Calculate the max area
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, d = 0;

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];

        // If the sum of the indices is even
        if ((r + c) % 2 == 0) {
            // If we are in the topmost row
            if (c == cols - 1) {
                r++;
            // If we are in the rightmost column
            } else if (r == 0) {
                c++;
            // Otherwise, move up diagonally
            } else {
                r--;
                c++;
            }
        } else {
            // If the sum of the indices is odd
            // If we are in the bottommost row
            if (r == rows - 1) {
                c++;
            // If we are in the leftmost column
            } else if (c == 0) {
                r++;
            // Otherwise, move down diagonally
            } else {
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the number to a character array of its digits
    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Find the rightmost digit that is smaller than a digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) that is larger than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits to the right of the original position i
    Arrays.sort(digits, i + 1, length);

    // Convert the array of characters back to an integer
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        return -1; // In case the number is out of integer range
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The length of the center symmetric numbers must be a positive integer.");
    }

    return generateCenterSymmetricNumbers(n, n);
}

private static List<String> generateCenterSymmetricNumbers(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return new ArrayList<>(Arrays.asList(""));
    }
    if (currentLength == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }

    List<String> prevList = generateCenterSymmetricNumbers(currentLength - 2, targetLength);
    List<String> result = new ArrayList<>();

    for (String s : prevList) {
        if (currentLength != targetLength) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }

    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be an array of three points with two coordinates each.");
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    // Calculate the area of the triangle formed by the points using the determinant method
    // Area = 0.5 * | x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2) |
    // If the area is 0, the points are collinear and do not form a boomerang
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int index2 = 0, index3 = 0, index5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            index2++;
            nextMultipleOf2 = uglyNumbers[index2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            index3++;
            nextMultipleOf3 = uglyNumbers[index3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            index5++;
            nextMultipleOf5 = uglyNumbers[index5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;
    char currentChar = s.charAt(0);

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentEnergy++;
        } else {
            currentChar = s.charAt(i);
            currentEnergy = 1;
        }
        maxEnergy = Math.max(maxEnergy, currentEnergy);
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) {
            return;
        }
        dfs(next, n, result);
    }
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> counts = new HashMap<>();
    for (int num : nums) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] dp = new int[n + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word);
        reversedWord.reverse();
        reversedSentence.append(reversedWord).append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().trim();
}
